// 1) simple shared-secret check (must match N8N_API_KEY in the Python .env)
const SECRET = 'CHANGE_ME';
const req = $input.first().json;
if ((req.headers || {})['x-api-key'] !== SECRET) {
  throw new Error('Unauthorized webhook call');
}

const b = req.body || {};
const alerts = b.alerts || [];
const s = b.summary || {};
const LIMIT = 3500; // WhatsApp text limit is 4096 chars

const head =
  `🚨 *Myntra Stock Alert*  (${b.part}/${b.parts})\n` +
  `Checked: ${s.total_checked ?? '-'} | Partial OOS: ${s.partial_oos ?? 0} | All OOS: ${s.all_oos ?? 0} | 404: ${s.not_found ?? 0}\n` +
  `⏱ ${s.seconds ?? '-'}s\n`;

const lines = alerts.map(a => {
  const tag = a.status === 'ALL_OOS' ? '🔴 ALL OUT' : '🟠 Size OOS';
  const who = [a.brand, a.name].filter(Boolean).join(' ').slice(0, 40);
  return `${tag} *${a.style_id}* ${who}\n   ❌ ${a.oos_sizes.join(', ')}\n   ${a.url}`;
});

if (!lines.length) {
  return [{ json: { text: head + '\n✅ Sab styles in stock hain.' } }];
}

const out = [];
let cur = head + '\n';
for (const l of lines) {
  if ((cur + l + '\n\n').length > LIMIT) { out.push({ json: { text: cur.trim() } }); cur = head + '\n'; }
  cur += l + '\n\n';
}
if (b.more_not_shown > 0 && b.part === b.parts) {
  cur += `…aur ${b.more_not_shown} styles. Poori list Excel report me hai: ${s.report || ''}`;
}
out.push({ json: { text: cur.trim() } });
return out;
